//const constants = require("./numeralConstants");
import { checkIfParamsAreNumbers } from "../logic/utils";

/**
 * calculates Bemf Iscale parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateBemfIScale(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersLd = inputStructure.parameters.parametersLd;
    const parametersRs = inputStructure.parameters.parametersRs;
    var ret;
    checkIfParamsAreNumbers([parametersLd, currentLoopSampleTime, parametersRs], (isValid) => {
        ret = isValid ? (parametersLd / (parametersLd + currentLoopSampleTime * parametersRs)) : NaN;
        // console.log("Sensorless BemfIScale:", ret);
    });
    return ret;

}

