/**
 * calculates Bemf WIscale parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateBemfWIScale(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersLd = inputStructure.parameters.parametersLd;
    const parametersLq = inputStructure.parameters.parametersLq;
    const parametersRs = inputStructure.parameters.parametersRs;
    var ret;
    checkIfParamsAreNumbers([parametersLd, parametersLq, currentLoopSampleTime, parametersRs], (isValid) => {
        ret = isValid ? (parametersLq * currentLoopSampleTime / (parametersLd + currentLoopSampleTime * parametersRs)) : NaN;
        // console.log("Sensorless BemfWIScale:", ret);
    });
    return ret;

}

/**
 * calculates Bemf Kp parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateBemfKp(inputStructure) {
    const parametersLd = inputStructure.parameters.parametersLd;
    const parametersRs = inputStructure.parameters.parametersRs;
    const sensorlessBemfObsrvF0 = inputStructure.sensorless.sensorlessBemfObsrvF0;
    const sensorlessBemfObsrvKsi = inputStructure.sensorless.sensorlessBemfObsrvKsi;
    var ret;
    checkIfParamsAreNumbers([parametersLd, parametersRs, sensorlessBemfObsrvF0, sensorlessBemfObsrvKsi], (isValid) => {
        ret = isValid ? ((2 * sensorlessBemfObsrvKsi * 2 * Math.PI * sensorlessBemfObsrvF0 * parametersLd - parametersRs)) : NaN;
        // console.log("Sensorless BemfKp:", ret);
    });
    return ret;
}

/**
 * calculates Bemf Ki parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateBemfKi(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersLd = inputStructure.parameters.parametersLd;
    const parametersRs = inputStructure.parameters.parametersRs;
    const sensorlessBemfObsrvF0 = inputStructure.sensorless.sensorlessBemfObsrvF0;
    var ret;
    checkIfParamsAreNumbers([parametersLd, parametersRs, sensorlessBemfObsrvF0, currentLoopSampleTime], (isValid) => {
        ret = isValid ? (parametersLd * Math.pow(2 * Math.PI * sensorlessBemfObsrvF0, 2) * currentLoopSampleTime) : NaN;
        // console.log("Sensorless BemfKi:", ret);
    });
    return ret;
}

/**
 * calculates Tracking observer Kp parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateTOKp(inputStructure) {
    const sensorlessTrackObsrvF0 = inputStructure.sensorless.sensorlessTrackObsrvF0;
    const sensorlessTrackObsrvKsi = inputStructure.sensorless.sensorlessTrackObsrvKsi;
    var ret;
    checkIfParamsAreNumbers([sensorlessTrackObsrvF0, sensorlessTrackObsrvKsi], (isValid) => {
        ret = isValid ? (2 * sensorlessTrackObsrvKsi * 2 * Math.PI * sensorlessTrackObsrvF0) : NaN;
        // console.log("Sensorless TOKp:", ret);
    });
    return ret;
}

/**
 * calculates Tracking observer Ki parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateTOKi(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const sensorlessTrackObsrvF0 = inputStructure.sensorless.sensorlessTrackObsrvF0;
    var ret;
    checkIfParamsAreNumbers([sensorlessTrackObsrvF0, currentLoopSampleTime], (isValid) => {
        ret = isValid ? (Math.pow(2 * Math.PI * sensorlessTrackObsrvF0, 2) * currentLoopSampleTime) : NaN;
        // console.log("Sensorless TOKi:", ret);
    });
    return ret;
}

/**
 * calculates Tracking observer Theta parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateTOTheta(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime], (isValid) => {
        ret = isValid ? (currentLoopSampleTime / Math.PI) : NaN;
        // console.log("Sensorless TOTheta:", ret);
    });
    return ret;
}

/**
 * calculates open loop start-up ramp increment parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateStartupInc(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersPp = inputStructure.parameters.parametersPp;
    const sensorlessStartupRamp = inputStructure.sensorless.sensorlessStartupRamp;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, parametersPp, sensorlessStartupRamp], (isValid) => {
        ret = isValid ? (sensorlessStartupRamp * currentLoopSampleTime / (60 / (parametersPp * 2 * Math.PI))) : NaN;
        // console.log("Sensorless StartupInc:", ret);
    });
    return ret;
}

/**
 * calculates open loop start-up merging speed parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateSpeedMerging(inputStructure) {
    const parametersPp = inputStructure.parameters.parametersPp;
    const sensorlessMergingSpeed = inputStructure.sensorless.sensorlessMergingSpeed;
    var ret;
    checkIfParamsAreNumbers([parametersPp, sensorlessMergingSpeed], (isValid) => {
        ret = isValid ? (sensorlessMergingSpeed / (60 / (parametersPp * 2 * Math.PI))) : NaN;
        // console.log("Sensorless SpeedMerging:", ret);
    });
    return ret;
}

/**
 * calculates open loop start-up merging speed parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateMergingCoeff(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersPp = inputStructure.parameters.parametersPp;
    const sensorlessMergingCoeff = inputStructure.sensorless.sensorlessMergingCoeff;
    const sensorlessMergingSpeed = inputStructure.sensorless.sensorlessMergingSpeed;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, parametersPp, sensorlessMergingCoeff, sensorlessMergingSpeed], (isValid) => {
        ret = isValid ? ( (Math.round((((sensorlessMergingCoeff / 100)* sensorlessMergingSpeed * parametersPp * currentLoopSampleTime)/60) * Math.pow(2, 15))) * 1/(Math.pow(2, 15)) ) : NaN;
        //console.log("Sensorless MergingCoeff:", ret);
    });
    return ret;
}

/**
 * calculates open loop start-up speed integrator gain parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
 function calculateStartupKiGain(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersNmax = inputStructure.parameters.parametersNmax;
    const parametersPp = inputStructure.parameters.parametersPp;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, parametersNmax, parametersPp], (isValid) => {
        ret = isValid ? 2*Math.PI*parametersPp*parametersNmax/60*currentLoopSampleTime/Math.PI : NaN;
        // console.log("Parameters Startup Ki gain:", ret);
    });
    return ret;
}

/**
 * calculates TO IIR filter B0 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateTOIirB0(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var TO_IIR_cutoff_freq = inputStructure.sensorless.sensorlessTrackObsrvIIRSpeedCutOff;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, TO_IIR_cutoff_freq], (isValid) => {
        ret = isValid ? (2 * Math.PI * TO_IIR_cutoff_freq * currentLoopSampleTime) / (2 + (2 * Math.PI * TO_IIR_cutoff_freq * currentLoopSampleTime)) : NaN;
        // console.log("Sensorless TOIirB0:", ret);
    });
    return ret;

}

/**
 * calculates TO IIR filter B1 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateTOIirB1(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var TO_IIR_cutoff_freq = inputStructure.sensorless.sensorlessTrackObsrvIIRSpeedCutOff;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, TO_IIR_cutoff_freq], (isValid) => {
        ret = isValid ? (2 * Math.PI * TO_IIR_cutoff_freq * currentLoopSampleTime) / (2 + (2 * Math.PI * TO_IIR_cutoff_freq * currentLoopSampleTime)) : NaN;
        // console.log("Sensorless TOIirB1:", ret);
    });
    return ret;
}

/**
 * calculates TO IIR filter A1 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateTOIirA1(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var TO_IIR_cutoff_freq = inputStructure.sensorless.sensorlessTrackObsrvIIRSpeedCutOff;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, TO_IIR_cutoff_freq], (isValid) => {
        ret = isValid ? -(2 * Math.PI * TO_IIR_cutoff_freq * currentLoopSampleTime - 2) / (2 + (2 * Math.PI * TO_IIR_cutoff_freq * currentLoopSampleTime)) : NaN;
        // console.log("Sensorless TOIirA1:", ret);
    });
    return ret;
}

/**
 * export function calculates the whole parameters output structure
 * @param {object} inputStructure 
 * @returns {object}
 */
export function calculateParams(inputStructure) {
    // console.log("Calculating Sensorless...");
    return {
        M1_I_SCALE: calculateBemfIScale(inputStructure),
        M1_U_SCALE: calculateBemfUScale(inputStructure),
        M1_E_SCALE: calculateBemfEScale(inputStructure),
        M1_WI_SCALE: calculateBemfWIScale(inputStructure),
        M1_BEMF_DQ_KP_GAIN: calculateBemfKp(inputStructure),
        M1_BEMF_DQ_KI_GAIN: calculateBemfKi(inputStructure),
        M1_TO_KP_GAIN: calculateTOKp(inputStructure),
        M1_TO_KI_GAIN: calculateTOKi(inputStructure),
        M1_TO_THETA_GAIN: calculateTOTheta(inputStructure),
        M1_OL_START_RAMP_INC: calculateStartupInc(inputStructure),
        "M1 Startup Ramp Dec": calculateStartupInc(inputStructure),
        M1_MERG_SPEED_TRH: calculateSpeedMerging(inputStructure),
        M1_MERG_COEFF: calculateMergingCoeff(inputStructure),
        "M1 StartUp Integ Ki": calculateStartupKiGain(inputStructure),
        M1_TO_SPEED_IIR_B0: calculateTOIirB0(inputStructure),
        M1_TO_SPEED_IIR_B1: calculateTOIirB1(inputStructure),
        M1_TO_SPEED_IIR_A1: calculateTOIirA1(inputStructure)
    }
}