<template>
  <section ref="midCanvas" v-if="visible">
    <div class="alert alert-warning" v-if="isWarning">
      <strong>Warning! </strong>
      <slot> {{ warningMessage }}</slot>
    </div>
    <div class="alert alert-danger" v-if="isWrong">
      <strong>Error! </strong>
      <slot> {{ errorMessage }}</slot>
    </div>

    <!-- Loop over main rows -->
    <div v-for="(row, rowIndex) in rows" :key="'row-' + rowIndex" 
         class="border-top border-bottom py-3 px-0 mb-2"
         :style="{
           'height': row.fixedHeight || 'auto'
         }">
      <div class="row g-4" :style="{ 
        height: row.fixedHeight ? '100%' : 'auto'
      }">
        <div class="col-12 col-md d-flex flex-column px-3"
          :class="{ 'border-end': colIndex !== row.columns.length - 1 }" v-for="(column, colIndex) in row.columns"
          :key="'col-' + colIndex"
          :style="{ 
            height: row.fixedHeight ? '100%' : 'auto',
            'overflow-y': row.fixedHeight ? 'auto' : 'visible',
            'overflow-x': 'hidden'
          }">
          <div class="d-flex flex-column h-100">
            <div v-for="section in column.sections" :key="section.name" class="mb-0">
              <span class="text-uppercase fw-bold d-block mb-2" v-if="section.name">
                {{ section.name }}
              </span>

              <!-- Horizontal layout -->
              <template v-if="section.layout === 'row'">
                <div class="d-flex flex-wrap align-items-start flex-nowrap mb-1" :class="{
                  'justify-content-between': section.align === 'between',
                  'justify-content-center': section.align === 'center'
                }">

                  <!-- Loop through items -->
                  <template v-for="item in section.fields" :key="item.id">
                    <!-- CHANGED: Replace the textarea for output items with a div that can render HTML -->
                    <div v-if="item.type === 'output'" class="d-flex align-items-start mb-1">
                      <label v-if="item.label" :for="item.id" class="me-2 mb-0 text-nowrap">
                        {{ item.label }}:
                      </label>
                      <!-- CHANGED: Use div with v-html instead of textarea for HTML content -->
                      <div :class="'form-control border-0 bg-transparent p-0 flex-grow-1 ' + item.className" :style="{
                        'overflow-wrap': 'break-word',
                        'word-wrap': 'break-word',
                        'white-space': (item.maxRows === 1) ? 'normal' : 'pre-wrap',
                        'min-height': ((item.maxRows || 3) * 1.5) + 'em'
                      }" :ref="item.id" v-html="item.value"></div>
                      <label v-if="item.unit" :for="item.id" class="ms-2 mb-0">
                        [{{ item.unit }}]
                      </label>
                    </div>
                    <!-- Input item (compact, aligned) -->
                    <div v-if="item.type === 'input'" class="d-flex align-items-center me-4" :title="item.hint"
                      style="min-width: 220px; max-width: 300px;">
                      <label v-if="item.label" :for="item.id" class="me-2 mb-0 text-nowrap">
                        {{ item.label }}:
                      </label>
                      <input :class="'form-control ' + item.className" style="width: 100%;" autocomplete="off"
                        :ref="item.id" :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                        @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)" />
                      <label v-if="item.unit" :for="item.id" class="ms-2 mb-0">
                        <span v-html="'[' + item.unit + ']'"></span>
                      </label>
                    </div>
                    <!-- Button item (compact, aligned left) -->
                    <div v-if="item.type === 'button'" class="d-flex align-items-center me-2" :title="item.hint">
                      <button :class="'btn navbar-text ' + item.className" style="min-width: max-content;" :id="item.id"
                        :disabled="item.disabled" @click="clickItem(item)">
                        {{ item.buttonLabel }}
                      </button>
                      <label v-if="item.unit" :for="item.id" class="ms-2 mb-0">
                        <span v-html="'[' + item.unit + ']'"></span>
                      </label>
                    </div>
                  </template>
                </div>
              </template>


              <!-- Vertical layout -->
              <template v-else>
                <div v-for="item in section.fields" :key="item.id" :title="item.hint">
                  <!-- Full-width text item -->
                  <div v-if="item.type === 'text'" class="row mb-2">
                    <div class="col-12 text-center">
                      <span :class="'d-block w-100 ' + item.className">
                        {{ item.label }}
                      </span>
                    </div>
                  </div>
                  <!-- Full-width output item (horizontal layout) - CHANGED TO DIV -->
                  <div v-if="item.type === 'output'" class="d-flex align-items-start mb-1">
                    <label v-if="item.label" :for="item.id" class="me-2 mb-0 text-nowrap">
                      {{ item.label }}:
                    </label>
                    <!-- CHANGED: Use div with v-html instead of textarea -->
                    <div :class="'form-control border-0 bg-transparent p-0 flex-grow-1 ' + item.className" :style="{
                      'overflow-wrap': 'break-word',
                      'word-wrap': 'break-word',
                      'white-space': (item.maxRows === 1) ? 'normal' : 'pre-wrap',
                      'min-height': ((item.maxRows || 3) * 1.5) + 'em',
                      'padding': '1px'
                    }" :ref="item.id" v-html="item.value"></div>
                    <label v-if="item.unit" :for="item.id" class="ms-2 mb-0">
                      [{{ item.unit }}]
                    </label>
                  </div>
                  <!-- Standard input/button layout -->
                  <div v-else-if="item.type === 'input' || item.type === 'button'" class="row mb-2">
                    <!-- Label column -->
                    <div class="col-3 d-flex align-items-center justify-content-end pe-0">
                      <label v-if="item.label" :for="item.id" class="me-1 mb-0 text-nowrap">
                        {{ item.label }}:
                      </label>
                    </div>

                    <!-- Input / Button column - aligned to left -->
                    <div class="col-6 d-flex align-items-center">
                      <input v-if="item.type === 'input'" :class="'form-control ' + item.className" autocomplete="off"
                        :ref="item.id" :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                        @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)" />
                      <button v-if="item.type === 'button'" :class="'btn navbar-text ' + item.className"
                        style="min-width: max-content; width: 100%;" :id="item.id" :disabled="item.disabled"
                        @click="clickItem(item)">
                        {{ item.buttonLabel }}
                      </button>
                    </div>

                    <!-- Unit column -->
                    <div class="col-3 d-flex align-items-center justify-content-start ps-0">
                      <label v-if="typeof item.unit !== 'undefined' && item.unit !== ''" :for="item.id" class="mb-0">
                        <span v-html="'[' + item.unit + ']'"></span>
                      </label>
                    </div>
                  </div>
                </div>
              </template>
            </div>
          </div>
        </div>
      </div>
    </div>
  </section>
</template>



<script>
import { getFieldById, formatNumber } from "../logic/utils";
import { styleText, cancelAllAwaitingFmstrWrites } from "../functions/userFunctions";
import { toBaseValue, setFieldFromBaseValue, addPrefixToUnit } from "../functions/scalingConfig";
export default {
  name: "MidCanvas",
  props: ["visible", "needData", "midOutputs", "midMeasureOutputs", "reloadData", "limits", "appState", "midMeasType", "midState", "midFinishedMeas", "midFaultsGlobal", "midFaultsPp", "midFaultsEl", "midFaultsMech", "diagFaultsCaptured", "diagFaultsPending", "M1DiagFaultsPending", "M1AppState", "midPpState", "midElState", "midMechState"],
  data() {
    return {
      isWrong: false,
      isWarning: false,
      warningMessage: "",
      errorMessage: "",
      mcatControl: false,
      isTransitioningWithDelay: false,
      isMechMeasAdvanced: false,
      rows: [
        {
          type: "midAppMidFinishedMeas",
          fixedHeight: "208px",
          columns: [
            {
              index: "status",
              sections: [
                {
                  name: "APP & MID status",
                  layout: "column",
                  fields: [
                    {
                      type: "output",
                      className: {
                        field: "form-control",
                        color: "",
                      },
                      id: "midActiveStateMachine",
                      label: "Currently active state machine",
                      unit: "",
                      disabled: true,
                      value: `${styleText("Spin", "STATE_SPIN")}`,
                      hasUnit: false,
                      hint: "Shows status of MID process",
                      maxRows: 1,
                    },
                    {
                      type: "output",
                      className: {
                        field: "form-control",
                        color: "",
                      },
                      id: "midStatusText",
                      label: "",
                      unit: "",
                      disabled: true,
                      value: `👋 ${styleText("WELCOME", "WELCOME")} to the Motor Parameters Identification (MID) Tool. Please enter the motor's nominal current '${styleText("I Nom", "TEXT_HIGHLIGHT")}' and speed '${styleText("N Nom", "TEXT_HIGHLIGHT")}'. Then proceed through the pole-pair identification assistant and continue with the remaining measurements in order.`,
                      hasUnit: false,
                      hint: "Shows status of MID process",
                      maxRows: 2,
                    },
                    {
                      type: "output",
                      className: {
                        field: "form-control",
                        color: "",
                      },
                      id: "midStatusTextSec",
                      label: "",
                      unit: "",
                      disabled: true,
                      value: "",
                      hasUnit: false,
                      hint: "Shows secondary information about MID process",
                      maxRows: 2,
                    },
                  ]
                },
              ]
            }
          ]
        },
        {
          type: "midInputParameters",
          columns: [
            {
              index: "midInParam",
              sections: [
                {
                  name: "Motor parameters for measurements",
                  layout: "row",
                  align: "center",
                  fields: [
                    {
                      type: "input",
                      id: "midInParamINom",
                      label: "I Nom",
                      unit: "A",
                      disabled: false,
                      value: "",
                      hasUnit: true,
                      hint: "Nominal DC current of the motor.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: 0.001,
                        maxRange: "",
                      },
                    },
                    {
                      type: "input",
                      id: "midInParamNNom",
                      label: "N Nom",
                      unit: "rpm",
                      disabled: false,
                      value: "",
                      hasUnit: true,
                      hint: "Nominal speed of the motor.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: 1,
                        maxRange: "",
                      },
                    },
                  ]
                },
              ]
            }
          ]
        },
        {
          type: "midMeasurements",
          columns: [
            {
              index: "midPolePairIA",
              sections: [
                {
                  name: "Pole-pair identification assistant",
                  layout: "column",
                  fields: [
                    {
                      type: "button",
                      id: "midPolePairIAUserButton",
                      disabled: false,
                      className: "btn nxp-light-blue",
                      label: "",
                      buttonLabel: "START",
                      unit: "",
                      hint: "Start pole-pair identification assistant",
                      value: 0,
                      textStart: "Pole-pair identification assistant in progress... The process begins with a single alignment, then performs one electrical revolution, stops for a few seconds, and repeats. Count the total number of stops during one mechanical revolution. Once the number of pole-pairs is determined, manually stop the identification assistant.",
                      textFinish: "Pole-pair identification assistant finished. Please enter the determined number of pole-pairs into the input cell and proceed with electrical parameters measurement.",
                      textStop: "Pole-pair identification assistant was manually stopped before completion.",
                    },  
                    {
                      type: "input",
                      id: "midPolePairIAPp",
                      label: "Pp",
                      unit: "-",
                      disabled: false,
                      value: "",
                      hasUnit: true,
                      hint: "Determined number of pole-pairs.",
                      validation: {
                        type: "number",
                        isFloat: false,
                        minRange: 1,
                        maxRange: 20,
                      },
                    },
                    {
                      type: "text",
                      id: "midPolePairIAText",
                      label: "Please enter the number of pole-pairs determined using the assistant to proceed.",
                      unit: "",
                      disabled: false,
                      value: "",
                      hasUnit: false,
                      hint: "Determined number of pole-pairs.",
                    },
                  ],
                },
              ],
            },
            {
              index: "midElParamMeas",
              sections: [
                {
                  name: "Electrical parameters measurement",
                  layout: "column",
                  fields: [
                    {
                      type: "button",
                      id: "midElParamMeasUserButton",
                      disabled: false,
                      className: "btn nxp-light-blue",
                      label: "",
                      buttonLabel: "START",
                      unit: "",
                      hint: "Start electrical parameters measurement",
                      value: 0,
                      textStart: "Electrical parameters measurement in progress...",
                      textFinish: "Electrical parameters measurement finished and results were loaded into the MCAT. Please proceed with mechanical parameters measurement.",
                      textStop: "Electrical parameters measurement was manually stopped before completion.",
                    }, 
                    {
                      type: "input",
                      id: "midElParamMeasRs",
                      label: "Rs",
                      unit: "Ohm",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated stator resistance.",
                    },
                    {
                      type: "input",
                      id: "midElParamMeasLd",
                      label: "Ld",
                      unit: "H",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated direct-axis inductance.",
                    },
                    {
                      type: "input",
                      id: "midElParamMeasLq",
                      label: "Lq",
                      unit: "H",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated quadrature-axis inductance.",
                    },
                    {
                      type: "input",
                      id: "midElParamMeasUdt",
                      label: "Udt",
                      unit: "V",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated dead time voltage drop.",
                    },
                  ],
                },
              ],
            },
            {
              index: "midMechParamMeas",
              sections: [
                {
                  name: "Mechanical parameters measurement",
                  layout: "column",
                  fields: [
                    {
                      type: "button",
                      id: "midMechParamMeasUserButton",
                      disabled: false,
                      className: "btn nxp-light-blue",
                      label: "",
                      buttonLabel: "START",
                      unit: "",
                      hint: "Start mechanical parameters measurement",
                      value: 0,
                      textStart: "Mechanical parameters measurement in progress...",
                      textFinish: "Mechanical parameters measurement finished and results were loaded into the MCAT. All MID steps have been successfully completed.",
                      textStop: "Mechanical parameters measurement was manually stopped before completion.",
                    },   
                    {
                      type: "input",
                      id: "midMechParamMeasKe",
                      label: "Ke",
                      unit: "V·s/rad",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated electrical constant.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: 0.00001,
                        maxRange: 0.1,
                      },
                    },
                    {
                      type: "input",
                      id: "midMechParamMeasKt",
                      label: "Kt",
                      unit: "Nm/rad",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated torque constant.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: 0.001,
                        maxRange: 1.0,
                      },
                    },
                    {
                      type: "input",
                      id: "midMechParamMeasJ",
                      label: "J",
                      unit: "g·m^2",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated moment of inertia.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: 0.001,
                        maxRange: 10000.0,
                      },
                    },
                    {
                      type: "input",
                      id: "midMechParamMeasA",
                      label: "A",
                      unit: "N·m",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated static friction torque, in 'basic' mode returns zero.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: "",
                        maxRange: "",
                      },
                    },
                    {
                      type: "input",
                      id: "midMechParamMeasB",
                      label: "B",
                      unit: "N·m·s/rad",
                      disabled: true,
                      value: "",
                      hasUnit: true,
                      hint: "Estimated friction coefficient, in 'basic' mode returns zero.",
                      validation: {
                        type: "number",
                        isFloat: true,
                        minRange: "",
                        maxRange: "",
                      },
                    },
                  ],
                },
              ],
            },
          ],
        },
      ],
    };
  },
methods: {
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
    getData() {
      const statusMid     = this.rows[0].columns[0].sections;
      const inputParam    = this.rows[1].columns[0].sections;
      const polePairIS    = this.rows[2].columns[0].sections;
      const elParamMeas   = this.rows[2].columns[1].sections;
      const mechParamMeas = this.rows[2].columns[2].sections;

      const statusMidOutData     = statusMid[0]    .fields;
      const inputParamInData     = inputParam[0]   .fields;
      const polePairISInData     = polePairIS[0]   .fields;
      const elParamMeasOutData   = elParamMeas[0]  .fields;
      const mechParamMeasOutData = mechParamMeas[0].fields;


      return {
        input: {
          inputParamInData,
          polePairISInData,
        },
        output:
        {
          statusMidOutData,
          elParamMeasOutData,
          mechParamMeasOutData,
        }
      };
    },
    /**
     * sets a value to a specific field given an id
     * @param {string} id
     * @param {number} baseValue - Value in base units (for calculations)
     * @returns {none}
     */
    setData(id, baseValue) {
      getFieldById(id, this.getData(), (field) => {
        setFieldFromBaseValue(field, baseValue);
      });
    },
    sendValue(id, displayValue, needsValidation) {
      // After first interaction with input, displayValue might be a string, so convert to number
      // console.log("CurrLopp 1: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      if(typeof displayValue == 'string'){
        displayValue = Number(displayValue); // Convert string to number
      }
      //console.log("CurrLoop 2: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);

      getFieldById(id, this.getData(), (field) => {
        const setError = () => {
          this.isWrong = true;
          field.className += " bg-danger";
          this.warningMessage = this.warningMessage.replace(war, "");
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (!this.errorMessage.includes(err)) {
            this.errorMessage += err;
          }
        };
        const setWarning = () => {
          this.isWarning = true;
          field.className += " bg-warning";
          this.errorMessage = this.errorMessage.replace(err, "");
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
          if (!this.warningMessage.includes(war)) {
            this.warningMessage += war;
          }
        };
        const type = field.validation.isFloat ? "float" : "integer";
        const war = `${field.label} is not in range [${field.validation.minRange} - ${field.validation.maxRange}]! `;
        const err = `${field.label} value is not a number of type ${type}! `;
        if (
          typeof displayValue !== "number" ||
          isNaN(displayValue) ||
          (!Number.isInteger(displayValue) && !field.validation.isFloat)
        ) {
          setError();
        } else if (
          (needsValidation && field.validation.minRange > displayValue) ||
          displayValue > field.validation.maxRange
        ) {
          setWarning();
        } else {
          this.errorMessage = this.errorMessage.replace(err, "");
          this.warningMessage = this.warningMessage.replace(war, "");
          field.className = "form-control";
          if (this.warningMessage === "") {
            this.isWarning = false;
          }
          if (this.errorMessage === "") {
            this.isWrong = false;
          }
        }
        
        // Remove the formatNumber call - keep the original value as entered by user
        field.value = displayValue;
      });
      
      if (!this.isWrong) {
        // Convert to base value before emitting for calculations
        const baseValue = toBaseValue(id, displayValue);
        this.$emit("value-was-sent", [id, baseValue]);

        // Check if this field has a FreeMASTER mapping and emit update request
        const freeMasterMappings = {
          "midPolePairIAPp": "MID: Known Param Pp",
        };
        
        if (freeMasterMappings[id]) {
          this.$emit("freemaster-update-request", {
            varName: freeMasterMappings[id],
            value: baseValue,
            fieldId: id
          });
        }

        this.errorMessage = "";
      }
    },
    initializeUnits() {
      try {
        const allFields = [
          ...this.getData().input.inputParamInData,
          ...this.getData().input.polePairISInData,
          ...this.getData().output.elParamMeasOutData,
          ...this.getData().output.mechParamMeasOutData,
        ];

        allFields.forEach(field => {
          if (field && field.type === 'input' && field.id && field.unit) {
            // Store original unit if not already stored
            if (!field.originalUnit) {
              field.originalUnit = field.unit;
            }
            // Update unit with prefix
            field.unit = addPrefixToUnit(field.id, field.originalUnit);
          }
        });
      } catch (error) {
        console.warn('Error initializing units:', error);
      }
    },
    clickItem(item)
    {
      /* Set variable signaling MID control from MCAT */
      this.$emit("user-action-request", [item, this]);
    },
    evaluateDiagFaultStatus() {
      const statusLine     = this.getData().output.statusMidOutData[1];
      const statusLineSec  = this.getData().output.statusMidOutData[2];
      const faultsPending  = this.diagFaultsPending;
      const faultsCaptured = this.diagFaultsCaptured;

      /* Report fault state to the status line, pending faults have higher priority */
      const midButtons = [
        this.getData().input.polePairISInData[0],
        this.getData().output.elParamMeasOutData[0],
        this.getData().output.mechParamMeasOutData[0]
      ];
      if (faultsPending > 0) {
        this.updateButtons(midButtons, { 
          disabled: true,
          value: 0,
          className: "bg-secondary",
          buttonLabel: "START"
        });
        statusLine.value = `❌ ${styleText("DIAG FAULT", "ERROR")} ${this.getFaultText(faultsPending, "pending")}`;
        statusLineSec.value = '';
      } else if (faultsCaptured > 0) {
        this.updateButtons(midButtons, { 
          disabled: false,
          value: 0,
          className: "nxp-light-blue",
          buttonLabel: "START"
        });
        statusLine.value = `❌ ${styleText("DIAG FAULT", "ERROR")} ${this.getFaultText(faultsCaptured, "captured")}`;
        statusLineSec.value = '';
        /* Enter 'Spin' state machine if MID process was started by MCAT, not variable watch */
        if(this.mcatControl === true) {
          this.$emit("user-action-request", ["midDeactivateMidFunction", this]);
        }
      }
    },
    getFaultText(val, type) {
      /* Define fault flags */
      const faultDescriptions = {
        0: { captured: "Over-current fault flag was captured.",  pending: "Over-current fault flag is pending."  },
        1: { captured: "Under-voltage fault flag was captured.", pending: "Under-voltage fault flag is pending." },
        2: { captured: "Over-voltage fault flag was captured.",  pending: "Over-voltage fault flag is pending."  },
      };

      /* Get fault flag text */
      const texts = [];
      for (const bit in faultDescriptions) {
        if ((val >> bit) & 1) {
          texts.push(faultDescriptions[bit][type]);
        }
      }
      return texts.join(" ");
    },
    updateButtons(buttons, options = {}) {
      // Convert single button to array for consistent handling
      const buttonArray = Array.isArray(buttons) ? buttons : [buttons];
      
      buttonArray.forEach(button => {
        if (options.disabled !== undefined) {
          button.disabled = options.disabled;
        }
        if (options.value !== undefined) {
          button.value = options.value;
        }
        if (options.className !== undefined) {
          button.className = options.className;
        }
        if (options.buttonLabel !== undefined) {
          button.buttonLabel = options.buttonLabel;
        }
      });
    }
  },
  mounted() {
    // Initialize units with prefixes when component mounts
    this.initializeUnits();
  },
  watch: {
    midOutputs: function (newVal) {
      const thisRef = this;
      if (newVal && newVal.id && typeof newVal.value !== 'undefined') {
        const id = newVal.id;
        const baseVal = newVal.value;
        const outputs = [
          "midPolePairIAPp",
          "midElParamMeasRs",
          "midElParamMeasLd",
          "midElParamMeasLq",
          "midElParamMeasUdt",
          "midMechParamMeasKe",
          "midMechParamMeasKt",
          "midMechParamMeasJ",
          "midMechParamMeasB",
          "midMechParamMeasA",
        ];
        
        try {
          getFieldById(id, thisRef.getData(), function (field) {
            if (field && outputs.includes(id) && !isNaN(baseVal)) {
              setFieldFromBaseValue(field, baseVal);
            }
          });
        } catch (error) {
          console.warn('Error processing midOutputs:', error);
        }
      }
    },
    midMeasureOutputs: function (newVal) {
      const thisRef = this;
      if (newVal && newVal.id && typeof newVal.value !== 'undefined') {
        const id = newVal.id;
        const val = newVal.value;
        
        try {
          getFieldById(id, thisRef.getData(), function (field) {
            if (field && !isNaN(val)) {
              field.value = formatNumber(val, 4);
              thisRef.sendValue(id, val, false);
            }
          });
        } catch (error) {
          console.warn('Error processing midMeasureOutputs:', error);
        }
      }
    },
    needData: function (newVal) {
      if (newVal) {
        this.$emit("test-data-was-sent", this.getData());
      }
    },
    reloadData: function (newVal) {
      const thisRef = this;
      if (newVal) {
        thisRef.setData(newVal.id, newVal.value);
      }
    },
    limits: function (newVal) {
      if (newVal) {
        const id = newVal.id;
        const value = newVal.value;
        const paramINom = this.getData().input.inputParamInData[0];
        const paramWNom = this.getData().input.inputParamInData[1];

        const setLimit = {
          parametersImax: () => {
            paramINom.validation.maxRange = value;
          },
          parametersNover: () => {
            paramWNom.validation.maxRange = value;
          },
        };
        if (typeof setLimit[id] !== "undefined") {
          setLimit[id]();
        }
      }
    },
    appState: function (newVal) {
        if (typeof newVal === 'undefined' || newVal === null) {
            return;
        }
        
        try {
            const stateMachineLine = this.getData().output.statusMidOutData[0];
            const statusLineSec = this.getData().output.statusMidOutData[2];
            
            if (!stateMachineLine || !statusLineSec) {
                return;
            }
            
            // State conversion table - maps numeric values to text descriptions
            const stateTextMap = {
                0: "MID",
                1: "MID->Spin transition",
                2: "Spin->MID transtion",
                3: "Spin", 
            };
            
            // Only execute if transitioning from MID to Spin and MCAT was controlling MID
            if (this.isTransitioningWithDelay === true) {
              // Reset transition flag when changing state
              if(stateTextMap[newVal] === "MID") {
                this.isTransitioningWithDelay = false;  
              } else if ((stateTextMap[newVal] === "Spin")) {
                this.isTransitioningWithDelay = false; 
                const midButtons = [
                  this.getData().input.polePairISInData[0],
                  this.getData().output.elParamMeasOutData[0],
                  this.getData().output.mechParamMeasOutData[0]
                ];
                this.updateButtons(midButtons, { 
                  disabled: false,
                  className: "nxp-light-blue",
                  value: 0,
                  buttonLabel: "START"
                });
              }
              statusLineSec.value = "";
            }

            if ((stateTextMap[newVal] === "Spin") && (this.mcatControl === true)) {
              this.mcatControl = false;
            }

            // Convert numeric state to text, fallback to "Unknown" if state not found
            const stateText = stateTextMap[newVal] || `Unknown State (${newVal})`;
            
            // Use STATE_MID style for MID state (0), STATE_SPIN for all others
            const styleLevel = (newVal === 0) ? "STATE_MID" : "STATE_SPIN";
            stateMachineLine.value = `${styleText(stateText, styleLevel)}`;
        } catch (error) {
            console.warn('Error processing appState:', error);
        }
    },
    midMeasType: function() {
      return;
    },
    midState: function (newVal) {
      const midButtons = [
        this.getData().input.polePairISInData[0],
        this.getData().output.elParamMeasOutData[0],
        this.getData().output.mechParamMeasOutData[0]
      ];
      const statusLine    = this.getData().output.statusMidOutData[1];
      const statusLineSec = this.getData().output.statusMidOutData[2];
      
      // Define state configurations
      const stateConfigs = {
        /* PP_ASSIST */ 1: { measType: 0, btnIdx: 0,     config: { disabled: false, value: 1, className: "btn-red",        buttonLabel: "STOP"  }},
        /* RL_ESTIM  */ 2: { measType: 1, btnIdx: 1,     config: { disabled: false, value: 1, className: "btn-red",        buttonLabel: "STOP"  }},
        /* BJ_ESTIM  */ 3: { measType: 2, btnIdx: 2,     config: { disabled: false, value: 1, className: "btn-red",        buttonLabel: "STOP"  }},
        /* STOP      */ 4: {                             config: { disabled: false, value: 0, className: "nxp-light-blue", buttonLabel: "START" }},
      };

      const stateConfig = stateConfigs[newVal];
      if (!stateConfig) {
        return;
      }
      
      // Apply configuration to appropriate button(s)
      switch (newVal) {
        case 1: /* PP_ASSIST */
        case 2: /* RL_ESTIM  */  
        case 3: /* BJ_ESTIM  */
          /* Disable all buttons */
          this.updateButtons(midButtons, { 
            disabled: true,
            className: "bg-secondary",
            buttonLabel: "START"
          });
          /* Update pressed button into "STOP" functionality */
          this.updateButtons(midButtons[stateConfigs[newVal].btnIdx], stateConfigs[newVal].config);
          statusLine.value = `ℹ️ ${styleText("INFO", "INFO")} ${midButtons[stateConfigs[newVal].btnIdx].textStart}`;
          statusLineSec.value = "";
          break;

        case 4: /* STOP */
          // Find state config with matching "midMeasType" value
          if(this.mcatControl === false) {
            const foundStateConfig = Object.values(stateConfigs).find(config => config.measType === this.midMeasType); 
            if(midButtons[foundStateConfig.btnIdx].value === 1) {
              const stoppedButton = midButtons[foundStateConfig.btnIdx];
              const isPpAssistant = stoppedButton.id === 'midPolePairIAUserButton';
              statusLine.value = `ℹ️ ${styleText("INFO", "INFO")} ${isPpAssistant ? stoppedButton.textFinish : stoppedButton.textStop}`;
              statusLineSec.value = "";
            }
            this.updateButtons(midButtons, stateConfigs[newVal].config);
          }
          break;

        default:
          break;
      }
    },
    midFinishedMeas: function (newVal, oldVal) {
      /* At the beginning of the measurement, the bit corresponding to the measurement type is reset, after the measurement is successfully finished the bit is set */
      const value = newVal - oldVal;  
      
      if (value > 0) {
        /* Measurement finished */
        const statusLine    = this.getData().output.statusMidOutData[1];
        const statusLineSec = this.getData().output.statusMidOutData[2];
        const midButtons = [
          this.getData().input .polePairISInData[0],
          this.getData().output.elParamMeasOutData[0],
          this.getData().output.mechParamMeasOutData[0]
        ];
        
        this.updateButtons(midButtons, { 
          disabled: false,
          value: 0,
          className: "nxp-light-blue",
          buttonLabel: "START"
        });

        /* Index map (measurement types and corresponding finish text buttons) */
        const finishTextIndexMap = {
          1: midButtons[0].textFinish,  // Pole-pair assistant
          2: midButtons[1].textFinish,  // Electrical parameters measurement
          4: midButtons[2].textFinish,  // Mechanical parameters measurement
        };
        const finishText = finishTextIndexMap[value];
        if (finishText) {
        statusLine.value = `✅ ${styleText("RESULT", "RESULT")} ${finishText}`;
        statusLineSec.value = "";
        } else {
          console.log("Unknown measurement finished.");
        }
        /* Enter 'Spin' state machine if MID process was started by MCAT, not variable watch */
        if(this.mcatControl === true) {
          this.$emit("user-action-request", ["midDeactivateMidFunction", this]);
        }
      } else {
        /* Measurement started */
        return;
      }
    },
    midFaultsGlobal: function (newVal) {
      const faultsPending  = this.diagFaultsPending;
      const faultsCaptured = this.diagFaultsCaptured;
      if ((newVal > 0) && (faultsPending === 0) && (faultsCaptured === 0))
      {
        /* Enable all MID buttons */
        const midButtons = [
          this.getData().input .polePairISInData[0],
          this.getData().output.elParamMeasOutData[0],
          this.getData().output.mechParamMeasOutData[0]
        ];
        const statusLine    = this.getData().output.statusMidOutData[1];
        const statusLineSec = this.getData().output.statusMidOutData[2];

        this.updateButtons(midButtons, { 
          disabled: false,
          value: 0,
          className: "nxp-light-blue",
          buttonLabel: "START"
        });
        
        /* Report fault state defined by set bit to the error bar */
        const faultGlobalDescriptions = {
          0: "Fault during initialization of pole-pair assistant.",
          1: "Fault during process of pole-pair assistant.",
          2: "Fault during initialization of electrical parameters measurement.",
          3: "Fault during measurement of electrical parameters.",
          4: "Fault during initialization of mechanical parameters measurement.",
          5: "Fault during measurement of mechanical parameters.",
        };
        const faultPpDescriptions = {
          0: "Missing openloop d-axis current.",
          1: "Missing required electrical speed.",
          2: "Missing sampling frequency.",
          3: "Duty cycle in frac exceedes limit.",
          4: "Invalid usage, must call init first.",
        };
        const faultElDescriptions = {
          0: "Missing sampling frequency.",
          1: "Sampling frequency below limit.",
          2: "Invalid positive DC current.",
          3: "Invalid negative DC current.",
          4: "Invalid number of Ld/Lq table measurements.",
          5: "Ld measurement current exceedes maximal positive DC current.",
          6: "Ld measurement current exceedes maximal negative DC current.",
          7: "Lq measurement current exceedes maximal positive DC current.",
          8: "Lq measurement current exceedes maximal negative DC current.",
          9: "Low sampling frequency (ratio to Hf current frequency.",
          10: "Invalid usage, must call init first.",
          11: "Low ratio between sampling frequency and Hf current frequency.",
          12: "Invalid AC current frequency.",
        };
        const faultMechDescriptions = {
          0: "Pole-pairs are not in valid range",
          1: "Missing electrical parameters",
          2: "Missing measurement current",
          3: "Missing nominal speed",
          4: "Missing sampling frequency",
          5: "Open-loop current exceeds measurement current",
          6: "Nominal speed out of limits",
          7: "Required speed for point 1 exceeds nominal speed",
          8: "Required speed for point 2 exceeds nominal speed",
          9: "Invalid usage, must call init first",
          10: "Could not reach steady state",
          11: "Could not found correct injected frequency",
        };
        
        /* Find which global fault bit is set (only one will be true) */
        const globalFaultText = [];
        for (const i in faultGlobalDescriptions) {
          if ((newVal >> i) & 1) {
            globalFaultText.push(faultGlobalDescriptions[i]);
          }
        }

        /* Report global fault to the status line */
        statusLine.value = `❌ ${styleText("FAULT", "ERROR")} ${globalFaultText}`;
        
        /* Determine detailed fault based on global fault bits and concatenate */
        let detailedFaultTexts = [];
        
        /* Pole-pair faults (midFaultsGlobal bits 0-1:) */
        if (((newVal >> 0) & 1) || ((newVal >> 1) & 1)) {
          for (const i in faultPpDescriptions) {
            if ((this.midFaultsPp >> i) & 1) {
              detailedFaultTexts.push(faultPpDescriptions[i]);
            }
          }
        }
        /* Electrical parameter faults (midFaultsGlobal bits 2-3:) */
        else if (((newVal >> 2) & 1) || ((newVal >> 3) & 1)) {
          for (const i in faultElDescriptions) {
            if ((this.midFaultsEl >> i) & 1) {
              detailedFaultTexts.push(faultElDescriptions[i]);
            }
          }
        }
        /* Mechanical parameter faults (midFaultsGlobal bits 4-5:) */
        else if (((newVal >> 4) & 1) || ((newVal >> 5) & 1)) {
          for (const i in faultMechDescriptions) {
            if ((this.midFaultsMech >> i) & 1) {
              detailedFaultTexts.push(faultMechDescriptions[i]);
            }
          }
        }
        
        /* Report detailed fault to the secondary status line */
        if (detailedFaultTexts.length > 0) {
          statusLineSec.value = `ℹ️ ${styleText("FAULT DESCRIPTION", "INFO")} ${detailedFaultTexts.join(" ")}`;
        } else {
          statusLineSec.value = "";
        }
        
        /* Enter 'Spin' state machine if MID process was started by MCAT, not variable watch */
        if(this.mcatControl === true) {
          this.$emit("user-action-request", ["midDeactivateMidFunction", this]);
        }
      }
    },
    midFaultsPp: function() {},
    midFaultsEl: function() {},
    midFaultsMech: function() {},
    diagFaultsCaptured() {
      /* Common handler for pending and captured diag fault status flags */
      this.evaluateDiagFaultStatus();
    },
    diagFaultsPending(newVal) {
      /* Common handler for pending and captured diag fault status flags */
      this.evaluateDiagFaultStatus();
      if(newVal > 0) {
        const statusLineSec = this.getData().output.statusMidOutData[2];
        statusLineSec.value = "";
        cancelAllAwaitingFmstrWrites();
      }
    },
    M1DiagFaultsPending: function (newVal) {
      /* Handle M1 diagnostic faults */
      const statusLine    = this.getData().output.statusMidOutData[1];
      const statusLineSec = this.getData().output.statusMidOutData[2];
      const midButtons = [
        this.getData().input.polePairISInData[0],
        this.getData().output.elParamMeasOutData[0],
        this.getData().output.mechParamMeasOutData[0]
      ];
      if (newVal > 0) {
        statusLine.value = `❌ ${styleText("DIAG FAULT", "ERROR")} M1 fault in '${styleText("Spin", "TEXT_HIGHLIGHT")}' state machine is pending, cannot transition to '${styleText("MID", "TEXT_HIGHLIGHT")}' state machine.`;
        statusLineSec.value = "";
        cancelAllAwaitingFmstrWrites();
        this.mcatControl = false;
        this.updateButtons(midButtons, { 
          disabled: true,
          value: 0,
          className: "bg-secondary",
          buttonLabel: "START"
        });
      } else {
        statusLine.value = `ℹ️ ${styleText("INFO", "INFO")} Diagnostic Fault M1 in '${styleText("Spin", "TEXT_HIGHLIGHT")}' state machine is no longer pending. Waiting for safe stop...`;
      }
    },
    M1AppState: function (newVal, oldVal) {
      const statusLine    = this.getData().output.statusMidOutData[1];
      const statusLineSec = this.getData().output.statusMidOutData[2];
      const midButtons = [
        this.getData().input.polePairISInData[0],
        this.getData().output.elParamMeasOutData[0],
        this.getData().output.mechParamMeasOutData[0]
      ];

      // M1 App State enum
      const M1_APP_STATE = {
        FAULT: 0,
        INIT:  1,
        STOP:  2,
        RUN:   3
      };

      // Check if transitioning from FAULT to STOP
      if (oldVal === M1_APP_STATE.FAULT && newVal === M1_APP_STATE.STOP) {
        statusLine.value = `ℹ️ ${styleText("INFO", "INFO")} Diagnostic Fault M1 in '${styleText("Spin", "TEXT_HIGHLIGHT")}' state machine was captured.`;
        statusLineSec.value = "";
        this.updateButtons(midButtons, { 
          disabled: false,
          value: 0,
          className: "nxp-light-blue",
          buttonLabel: "START"
        });
      }
    },
    midPpState: function (newVal) {
      if(this.midState === 1){
        const statusLineSec = this.getData().output.statusMidOutData[2];
        
        const ppState = {
          /* UNINITIALIZED */     0: ``, 
          /* ROTATE */            1: `Rotor rotating.`,
        };
        
        if ((newVal) &&
        (ppState[newVal]) &&
        (this.diagFaultsPending === 0) &&
        (this.diagFaultsCaptured === 0) && 
        (this.midFinishedMeas === 0)) {
          statusLineSec.value = `ℹ️ ${styleText("STATE", "INFO")} ${ppState[newVal]}`;
        }
      }
    },
    midElState: function (newVal) {
      if(this.midState ===2){
        const statusLineSec = this.getData().output.statusMidOutData[2];

        const elState = {
          /* UNINITIALIZED */     0: ``, 
          /* MEAS_LD */           1: `Measurement of d-axis inductance.`,
          /* MEAS_LQ */           2: `Measurement of q-axis inductance.`,
          /* LD_TO_LQ */          3: `Transition between axes.`,
          /* POSTPROCESS_LD */    4: `Postprocessing of accumulated values for d-axis measurement.`,
          /* POSTPROCESS_LQ */    5: `Postprocessing of accumulated values for q-axis measurement.`,
          /* UNWIND */            6: `Gradual turn-off of the DC current at the end of measurement.`,
        };

        if ((newVal) &&
            (elState[newVal]) &&
            (this.diagFaultsPending === 0) &&
            (this.diagFaultsCaptured === 0) && 
            (this.midFinishedMeas === 0)) {
          statusLineSec.value = `ℹ️ ${styleText("STATE", "INFO")} ${elState[newVal]}`;
        }
      }
    },
    midMechState: function (newVal, oldVal) {
      if(this.midState ===3){
        const statusLineSec = this.getData().output.statusMidOutData[2];

        const mechStateBasic = {
          /* UNINITIALIZED */       0: ``, 
          /* ROTOR_ALIGN */         1: `Rotor alignment.`,
          /* OPEN_LOOP_STARTUP */   2: `Open-loop startup.`,
          /* FLUX_ESTIM */          3: `Measurement of parameters ${styleText("Ke", "TEXT_HIGHLIGHT")} and ${styleText("Kt", "TEXT_HIGHLIGHT")} at speed point 1.`,
          /* FREQ_SELECT */         4: `Selection of injected frequency.`,
          /* PARAM_EST_MEAS */      5: `Measurement of parameter ${styleText("J", "TEXT_HIGHLIGHT")} at speed point 1.`,
        };
        const mechStateAdvanced = {
          /* UNINITIALIZED */       0: ``, 
          /* ROTOR_ALIGN */         1: `Rotor alignment.`,
          /* OPEN_LOOP_STARTUP */   2: `Open-loop startup.`,
          /* FLUX_ESTIM */          3: `Acquisition of speed point 2 and measurement of parameters ${styleText("Ke", "TEXT_HIGHLIGHT")} and ${styleText("Kt", "TEXT_HIGHLIGHT")}.`,
          /* FREQ_SELECT */         4: `Selection of injected frequency.`,
          /* PARAM_EST_MEAS */      5: `Measurement of parameters ${styleText("J", "TEXT_HIGHLIGHT")}, ${styleText("B", "TEXT_HIGHLIGHT")} and ${styleText("A", "TEXT_HIGHLIGHT")} at speed point 2.`,
        };

        /* Reset flag when mechanical measurement starts (ROTOR_ALIGN or OPEN_LOOP_STARTUP state) */
        if ((newVal === 1) || (newVal === 2)) {
          this.isMeasurementTypeAdvanced = false;
        }

        // Set flag only once when transitioning from PARAM_EST_MEAS (5) to FLUX_ESTIM (3)
        if (oldVal === 5 && newVal === 3 && !this.isMechMeasurementCycling) {
          this.isMeasurementTypeAdvanced = true;
        }

        const mechState = this.isMeasurementTypeAdvanced ? mechStateAdvanced : mechStateBasic;
        if ((newVal) &&
            (mechState[newVal]) &&
            (this.diagFaultsPending === 0) &&
            (this.diagFaultsCaptured === 0) && 
            (this.midFinishedMeas === 0)) {
          statusLineSec.value = `ℹ️ ${styleText("STATE", "INFO")} ${mechState[newVal]}`;
        }
      }
    }
  },
};
</script>