const constants = require("./numeralConstants");
import { checkIfParamsAreNumbers } from "../logic/utils";

/**
 * calculates motor's maximum frequency
 * @param {object} inputStructure
 * @returns {number} max frequency
 * 
 */
function calculateM1FreqMax(inputStructure) {
    const parametersNmax = inputStructure.parameters.parametersNmax;
    const parametersPp = inputStructure.parameters.parametersPp;
    var ret;

    // Maximal electric frequency [RPM * Pp / 60] -> [el max speed in Hz]
    checkIfParamsAreNumbers([parametersNmax, parametersPp], (isValid) => {
        ret = isValid ? parametersNmax * parametersPp / 60  : NaN;
        // console.log("Parameters FreqMax:", ret);
    });
    return ret;
}

/**
 * calculates motor alignment duration
 * @param {object} inputStructure
 * @returns {number} align duration
 * 
 */
 function calculateM1AlignDuration(inputStructure) {
    const parametersAlignDuration = inputStructure.parameters.parametersAlignDuration;
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var ret;
    checkIfParamsAreNumbers([parametersAlignDuration, currentLoopSampleTime], (isValid) => {
        ret = isValid ? parametersAlignDuration / currentLoopSampleTime : NaN;
        // console.log("Parameters AlignDuration:", ret);
    });
    return ret;
}

