/**
 * calculates B0 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1UdcbIirB0(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const UDCB_IIR_cutoff_freq = inputStructure.parameters.parametersUdcbIIRf0;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime], (isValid) => {
        ret = isValid ? (2 * Math.PI * UDCB_IIR_cutoff_freq * currentLoopSampleTime) / (2 + (2 * Math.PI * UDCB_IIR_cutoff_freq * currentLoopSampleTime)) : NaN;
        // console.log("Parameters UdcbIirB0:", ret);
    });
    return ret;

}

/**
 * calculates B1 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1UdcbIirB1(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const UDCB_IIR_cutoff_freq = inputStructure.parameters.parametersUdcbIIRf0;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime], (isValid) => {
        ret = isValid ? (2 * Math.PI * UDCB_IIR_cutoff_freq * currentLoopSampleTime) / (2 + (2 * Math.PI * UDCB_IIR_cutoff_freq * currentLoopSampleTime)) : NaN;
        // console.log("Parameters UdcbIirB1:", ret);
    });
    return ret;
}

/**
 * calculates A1 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1UdcbIirA1(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const UDCB_IIR_cutoff_freq = inputStructure.parameters.parametersUdcbIIRf0;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime], (isValid) => {
        ret = isValid ? -(2 * Math.PI * UDCB_IIR_cutoff_freq * currentLoopSampleTime - 2) / (2 + (2 * Math.PI * UDCB_IIR_cutoff_freq * currentLoopSampleTime)) : NaN;
        // console.log("Parameters UdcbIirA1:", ret);
    });
    return ret;
}

/**
 * calculates V/Hz factor gain
 * @param {object} inputStructure 
 * @returns {number}
 */
 function calculateScalarVHzFactorGain(inputStructure) {
    const parametersUphNom = inputStructure.parameters.parametersUphNom;
    const parametersNnom = inputStructure.parameters.parametersNnom;
    const parametersPp = inputStructure.parameters.parametersPp;
    var parametersScalarVHzRatio = inputStructure.parameters.parametersScalarVHzRatio;
    var ret;
    checkIfParamsAreNumbers([parametersUphNom, parametersNnom, parametersPp, parametersScalarVHzRatio], (isValid) => {
        ret = isValid ? parametersUphNom*parametersScalarVHzRatio/100/(parametersNnom*parametersPp/60) : NaN;
        // console.log("Parameters ScalarVHzFactorGain:", ret);
    });
    return ret;
}

/**
 * calculates Scalar integration gain
 * @param {object} inputStructure 
 * @returns {number}
 */
 function calculateScalarIntegGain(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const parametersNmax = inputStructure.parameters.parametersNmax;
    const parametersPp = inputStructure.parameters.parametersPp;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, parametersNmax, parametersPp], (isValid) => {
        ret = isValid ? 2*Math.PI*parametersPp*parametersNmax/60*currentLoopSampleTime/Math.PI : NaN;
        // console.log("Parameters ScalarIntegGain:", ret);
    });
    return ret;
}

/**
 * calculates Scalar Ramp Up coefficient
 * @param {object} inputStructure 
 * @returns {number}
 */
 function calculateScalarRampUp(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const speedLoopRampUp = inputStructure.speedLoop.speedLoopIncUp;
    const parametersPp = inputStructure.parameters.parametersPp;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, speedLoopRampUp, parametersPp], (isValid) => {
        ret = isValid ? speedLoopRampUp*currentLoopSampleTime*parametersPp/60 : NaN;
        //  console.log("Parameters Scalar Ramp Up:", ret);
    });
    return ret;
}

/**
 * calculates Scalar Ramp Down coefficient
 * @param {object} inputStructure 
 * @returns {number}
 */
 function calculateScalarRampDown(inputStructure) {
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    const speedLoopRampDown = inputStructure.speedLoop.speedLoopIncDown;
    const parametersPp = inputStructure.parameters.parametersPp;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, speedLoopRampDown, parametersPp], (isValid) => {
        ret = isValid ? speedLoopRampDown*currentLoopSampleTime*parametersPp/60 : NaN;
        //  console.log("Parameters Scalar Ramp Down:", ret);
    });
    return ret;
}

/**
 * export function calculates the whole parameters output structure
 * @param {object} inputStructure 
 * @returns {object}
 */
export function calculateParams(inputStructure) {
    // console.log("Calculating Parameters...");
    return {
        M1_U_MAX: calculateM1Umax(inputStructure),
        M1_FREQ_MAX: calculateM1FreqMax(inputStructure),
        M1_ALIGN_DURATION: calculateM1AlignDuration(inputStructure),
        M1_CALIB_DURATION: calculateM1CalibDuration(inputStructure),
        M1_FAULT_DURATION: calculateM1FaultDuration(inputStructure),
        M1_FREEWHEEL_DURATION: calculateM1FreewheelDuration(inputStructure),
        M1_E_BLOCK_PER: inputStructure.parameters.parametersEblockPer,
        M1_SPEED_ANGULAR_SCALE: calculateM1SpeedAngularScale(inputStructure),
        M1_N_MIN: calculateM1SpeedMin(inputStructure),
        M1_N_MAX: calculateM1SpeedMax(inputStructure),
        M1_N_ANGULAR_MAX: calculateM1SpeedAngularMax(inputStructure),
        M1_N_NOM: calculateM1SpeedNom(inputStructure),
        M1_N_OVERSPEED: calculateM1SpeedOver(inputStructure),
        M1_UDCB_IIR_B0: calculateM1UdcbIirB0(inputStructure),
        M1_UDCB_IIR_B1: calculateM1UdcbIirB1(inputStructure),
        M1_UDCB_IIR_A1: calculateM1UdcbIirA1(inputStructure),
        M1_SCALAR_VHZ_FACTOR_GAIN: calculateScalarVHzFactorGain(inputStructure),
        M1_SCALAR_INTEG_GAIN: calculateScalarIntegGain(inputStructure),
        M1_SCALAR_RAMP_UP: calculateScalarRampUp(inputStructure),
        M1_SCALAR_RAMP_DOWN: calculateScalarRampDown(inputStructure)
    }
}
