const userStart = "/* USER INPUT START */";
const userEnd = "/* USER INPUT END */";

export function extractComments(contents) {
    var starts = [];
    var ends = [];
    contents.split("\n").forEach(function (line, index) {
        if (line.startsWith("/*")) {
            starts.push(index);
        }
        if (line.startsWith("*/")) {
            ends.push(index);
        }
    });
    return {
        start: starts,
        end: ends
    }
}

export function extractDataFromFile(comments, contents) {
    const lines = contents.split("\n");
    return {
        copyright: lines.slice(comments.start[0], comments.end[0] + 1).join("\n"),
        metadata: lines.slice(comments.start[1], comments.end[1] + 1).join("\n"),
        parsedData: lines.slice(comments.start[2] + 1, comments.end[2]).join("\n"),
        motorIdentification: lines.slice(comments.start[3] + 1, comments.end[3]).join("\n"),
        userInput: lines.slice(comments.start[comments.start.length - 2], comments.start[comments.start.length - 1] + 1).join("\n"),
    }

}

export function validateOutputFile(data, commentsData) {
    const validateLicense = (text) => {
        return text.includes("License") && text.includes("Copyright");
    }
    const validateMetadata = (text) => {
        // return text.includes("FILE NAME: ") && text.includes("DATE: ");
        return text.length > 0;
    }
    const validateData = (text) => {
        try {
            const mainKeys = (() => {
                var keys = [];
                Object.keys(data).forEach((canvas) => {
                    data[canvas].forEach((field) => {
                        keys.push(field.id);
                    });
                });
                return keys;
            })();
            const object = JSON.parse(text, function (key, value) {
                return (typeof value === "string" || isNaN(value)) || typeof(value) === "boolean" ? value : parseFloat(value);
            }); 
            const filtered = Object.keys(data).reduce((res, item) => {
                res[Object.keys(object).includes(item) ? "present" : "notPresent" ].push(item);
                return res;
            }, { present: [], notPresent: [] });
            if (filtered.notPresent.length > 1) {
                console.log("Invalid canvas data - canvas from file not present in main data");
                return false;
            }
            if (!Object.keys(object).every((canvas) => Object.keys(data).includes(canvas))) {
                console.log("Invalid canvas data - canvas from main data not present in canvas");
                return false;
            }
            Object.keys(object).forEach((canvas) => {
                if (!Object.keys(object[canvas]).every((key) => mainKeys.includes(key))) {
                    console.log("Invalid field keys - key from file not present in main data");
                    return false
                }
                if (!Object.values(object[canvas]).every((value) => ["boolean", "number"].includes(typeof value))) {
                    console.log("Invalid value types - should be number or boolean");
                    return false;
                }
            });
            return true;
        } catch (error) {
            console.log("Cannot parse JSON input object - invalid structure: ", error, commentsData);
            return false;
        }
    }
    const validateMotorIdentification = (motorIdentification) => {
        try {
            const motors = JSON.parse(motorIdentification);
            return ["motorName", "motorDescription"].every((key) => Object.keys(motors).includes(key));
        } catch (error) {
            console.log("Cannot parse JSON motor object - invalid structure", error);
            return false;
        }
    }
    const validateUserInput = (userInput) => {
        return [userInput.includes(userStart), userInput.includes(userEnd)].every((bool) => bool === true);
    }     
    if (Object.keys(commentsData).length !== 5) {
        console.log("Cannot extract comments from input file");
        return false;
    } else {
        const copyright = commentsData.copyright;
        if (!validateLicense(copyright)) {
            console.log("Invalid license - should be NXP BSD-3-Clause");
            return false;
        }
        const metadata = commentsData.metadata;
        if (!validateMetadata(metadata)) {
            console.log("Invalid file data");
            return false;
        }
        const parsedData = commentsData.parsedData;
        if (!validateData(parsedData)) {
            console.log("Invalid fields data");
            return false;
        }
        const motorIdentification = commentsData.motorIdentification;
        if (!validateMotorIdentification(motorIdentification)) {
            console.log("Invalid motor identification");
            return false;
        }
        const userInput = commentsData.userInput;
        if (!validateUserInput(userInput)) {
            console.log("User input marks not present");
            return false;
        }
        return true;
    }
}