import { formatNumber } from '../logic/utils.js';
import { styleText } from './userFunctions.js';

/* Unit scale definitions with their powers of 10 */
const UNIT_SCALES = {
  'GIGA':  9,   // 10^9
  'MEGA':  6,   // 10^6
  'KILO':  3,   // 10^3
  'UNIT':  0,   // 10^0 (base unit)
  'MILLI': -3,  // 10^-3
  'MICRO': -6,  // 10^-6
  'NANO':  -9,  // 10^-9
};

/* Unit prefixes for display */
const UNIT_PREFIXES = {
  'GIGA':  'G',
  'MEGA':  'M',
  'KILO':  'k',
  'UNIT':  '',
  'MILLI': 'm',
  'MICRO': 'μ',
  'NANO':  'n',
};

/**
 * Central scaling configuration for all parameters
 * Format: { from: 'SOURCE_SCALE', to: 'TARGET_SCALE' }
 */
export const PARAMETER_SCALING = {
  // MID Parameters
  midElParamMeasLd:   { from: 'UNIT', to: 'MILLI' },  // H          ->  mH
  midElParamMeasLq:   { from: 'UNIT', to: 'MILLI' },  // H          ->  mH  
  midElParamMeasUdt:  { from: 'UNIT', to: 'MILLI' },  // V          ->  mV
  midMechParamMeasKe: { from: 'UNIT', to: 'MILLI' },  // V·s/rad    ->  mV·s/rad
  midMechParamMeasKt: { from: 'UNIT', to: 'MILLI' },  // Nm/A       ->  mNm/A
  midMechParamMeasJ:  { from: 'KILO', to: 'MILLI' },  // kg·m²      ->  mg·m²
  midMechParamMeasB:  { from: 'UNIT', to: 'MICRO' },  // N·m·s/rad  ->  μN·m·s/rad
  midMechParamMeasA:  { from: 'UNIT', to: 'MILLI' },  // N·m        ->  mN·m
  
  // Motor Parameters
  parametersLd:       { from: 'UNIT', to: 'MILLI' },  // H          ->  mH
  parametersLq:       { from: 'UNIT', to: 'MILLI' },  // H          ->  mH
  parametersKt:       { from: 'UNIT', to: 'MILLI' },  // V·s/rad    ->  mV·s/rad
  parametersJ:        { from: 'KILO', to: 'MILLI' },  // kg·m²      ->  mg·m²
};

/**
 * Get scaling configuration for a parameter
 */
export function getScaling(parameterId) {
  return PARAMETER_SCALING[parameterId] || { from: 'UNIT', to: 'UNIT' };
}

/**
 * Calculate conversion factor between two unit scales
 */
export function calculateConversionFactor(fromScale, toScale) {
  const fromPower = UNIT_SCALES[fromScale];
  const toPower = UNIT_SCALES[toScale];
  
  if (fromPower === undefined || toPower === undefined) {
    console.warn(`Unknown unit scale: ${fromScale} or ${toScale}`);
    return 1;
  }
  
  // Convert from source scale to target scale
  // Example: UNIT to MILLI = 10^0 to 10^-3 = multiply by 10^3 = 1000
  return Math.pow(10, fromPower - toPower);
}

/**
 * Convert base unit value to display value
 */
export function toDisplayValue(parameterId, baseValue) {
  const scaling = getScaling(parameterId);
  const conversionFactor = calculateConversionFactor(scaling.from, scaling.to);
  return baseValue * conversionFactor;
}

/**
 * Convert display value to base unit value (for calculations)
 */
export function toBaseValue(parameterId, displayValue) {
  const scaling = getScaling(parameterId);
  const conversionFactor = calculateConversionFactor(scaling.from, scaling.to);
  
  if (conversionFactor === 1) {
    return displayValue;
  }
  
  return displayValue / conversionFactor;
}

/**
 * Get unit prefix based on target scale
 */
export function getUnitPrefix(parameterId) {
  const scaling = getScaling(parameterId);
  return UNIT_PREFIXES[scaling.to] || '';
}

/**
 * Add prefix to existing unit based on scaling configuration
 */
export function addPrefixToUnit(parameterId, originalUnit) {
  const prefix = getUnitPrefix(parameterId);
  if (!prefix) {
    return originalUnit;
  }
  
  const styledPrefix = styleText(prefix, 'PREFIX_UNIT');
  return styledPrefix + originalUnit;
}

/**
 * Update field with base value from calculations/FreeMASTER
 * Preserves original unit and adds prefix if needed
 */
export function setFieldFromBaseValue(field, baseValue) {
  const displayValue = toDisplayValue(field.id, baseValue);
  
  // Format based on field validation settings
  if (field.validation && field.validation.isFloat === false) {
    // Field should be integer - don't use formatNumber
    field.value = Math.round(displayValue);
  } else {
    // Field can be float - use formatNumber
    field.value = formatNumber(displayValue, 4);
  }

  //console.log(`Item with id "${field.id}" was updated with value "${field.value}"`);
  
  // Add prefix to existing unit if scaling is applied
  const prefix = getUnitPrefix(field.id);
  if (prefix && field.unit && !field.unit.startsWith(prefix)) {
    // Store original unit if not already stored
    if (!field.originalUnit) {
      field.originalUnit = field.unit;
    }
    field.unit = addPrefixToUnit(field.id, field.originalUnit);
  }
}

/**
 * Utility function to add new parameter scaling
 */
export function addParameterScaling(parameterId, fromScale, toScale) {
  PARAMETER_SCALING[parameterId] = { from: fromScale, to: toScale };
}

/**
 * Get available unit scales
 */
export function getAvailableScales() {
  return Object.keys(UNIT_SCALES);
}

/**
 * Get conversion factor for debugging/testing
 */
export function getConversionFactor(parameterId) {
  const scaling = getScaling(parameterId);
  return calculateConversionFactor(scaling.from, scaling.to);
}
