/**
 * calculates B0 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1SpeedIirB0(inputStructure) {
    const speedLoopSampleTime = inputStructure.speedLoop.speedLoopSampleTime;
    const speedLoopCutOffFreq = inputStructure.speedLoop.speedLoopCutOffFreq;
    var ret;
    checkIfParamsAreNumbers([speedLoopSampleTime, speedLoopCutOffFreq], (isValid) => {
        ret = isValid ? (2 * Math.PI * speedLoopCutOffFreq * speedLoopSampleTime) / (2 + (2 * Math.PI * speedLoopCutOffFreq * speedLoopSampleTime)) : NaN;
        // console.log("SpeedLoop SpeedIirB0:", ret);
    });
    return ret;
}

/**
 * calculates B1 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1SpeedIirB1(inputStructure) {
    const speedLoopSampleTime = inputStructure.speedLoop.speedLoopSampleTime;
    const speedLoopCutOffFreq = inputStructure.speedLoop.speedLoopCutOffFreq;
    var ret;
    checkIfParamsAreNumbers([speedLoopSampleTime, speedLoopCutOffFreq], (isValid) => {
        ret = isValid ? (2 * Math.PI * speedLoopCutOffFreq * speedLoopSampleTime) / (2 + (2 * Math.PI * speedLoopCutOffFreq * speedLoopSampleTime)) : NaN;
        // console.log("SpeedLoop SpeedIirB1:", ret);
    });
    return ret;
}

/**
 * calculates A1 parameter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1SpeedIirA1(inputStructure) {
    const speedLoopSampleTime = inputStructure.speedLoop.speedLoopSampleTime;
    const speedLoopCutOffFreq = inputStructure.speedLoop.speedLoopCutOffFreq;
    var ret;
    checkIfParamsAreNumbers([speedLoopSampleTime, speedLoopCutOffFreq], (isValid) => {
        ret = isValid ? -(2 * Math.PI * speedLoopCutOffFreq * speedLoopSampleTime - 2) / (2 + (2 * Math.PI * speedLoopCutOffFreq * speedLoopSampleTime)) : NaN;
        // console.log("SpeedLoop SpeedIirA1:", ret);
    });
    return ret;
}




/**
 * calculates B0 parameter of speed ZC filter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1SpeedIirZCB0(inputStructure) {
    const speedLoopSampleTime = inputStructure.speedLoop.speedLoopSampleTime;
    const kp_w = calculateSpeedKpGain(inputStructure); // Z and S domain has the same value
    const ki_w_z = calculateSpeedKiGain(inputStructure); // in Z domain
    const ki_w_s = ki_w_z * (2/speedLoopSampleTime); // in S domain
    var Tfilt = kp_w/ki_w_s; // Ti = kp_w/ki_w
    var ret;
    checkIfParamsAreNumbers([speedLoopSampleTime, Tfilt], (isValid) => {
        ret = isValid ? (speedLoopSampleTime / (speedLoopSampleTime + 2 * Tfilt )) : NaN;
        // console.log("ZC B0:", ret);
    });
    return ret;
}

/**
 * calculates B1 parameter of speed ZC filter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1SpeedIirZCB1(inputStructure) {
    const speedLoopSampleTime = inputStructure.speedLoop.speedLoopSampleTime;
    const kp_w = calculateSpeedKpGain(inputStructure); // Z and S domain has the same value
    const ki_w_z = calculateSpeedKiGain(inputStructure); // in Z domain
    const ki_w_s = ki_w_z * (2/speedLoopSampleTime); // in S domain
    var Tfilt = kp_w/ki_w_s; // Tfilt = Ti = kp_w/ki_w
    var ret;
    checkIfParamsAreNumbers([speedLoopSampleTime, Tfilt], (isValid) => {
        ret = isValid ? (speedLoopSampleTime / (speedLoopSampleTime + 2 * Tfilt )) : NaN;
        // console.log("ZC B1:", ret);
    });
    return ret;
}

/**
 * calculates A1 parameter of speed ZC filter
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1SpeedIirZCA1(inputStructure) {
    const speedLoopSampleTime = inputStructure.speedLoop.speedLoopSampleTime;
    const kp_w = calculateSpeedKpGain(inputStructure); // Z and S domain has the same value
    const ki_w_z = calculateSpeedKiGain(inputStructure); // in Z domain
    const ki_w_s = ki_w_z * (2/speedLoopSampleTime); // in S domain
    var Tfilt = kp_w/ki_w_s; // Tfilt = Ti = kp_w/ki_w
    var ret;
    checkIfParamsAreNumbers([speedLoopSampleTime, Tfilt], (isValid) => {
        ret = isValid ? (-1)*(speedLoopSampleTime - 2 * Tfilt) / (speedLoopSampleTime + 2 * Tfilt ) : NaN;
        // console.log("ZC A1:", ret);
    });
    return ret;
}


/**
 * export function calculates the whole parameters output structure
 * @param {object} inputStructure 
 * @returns {object}
 */
export function calculateParams(inputStructure) {
    return {
        M1_SPEED_PI_PROP_GAIN: calculateSpeedKpGain(inputStructure),
        M1_SPEED_PI_INTEG_GAIN: calculateSpeedKiGain(inputStructure),
        M1_SPEED_RAMP_UP: calculateM1SpeedRampUp(inputStructure),
        M1_SPEED_RAMP_DOWN: calculateM1SpeedRampDown(inputStructure),
        M1_SPEED_IIR_B0: calculateM1SpeedIirB0(inputStructure),
        M1_SPEED_IIR_B1: calculateM1SpeedIirB1(inputStructure),
        M1_SPEED_IIR_A1: calculateM1SpeedIirA1(inputStructure),
        M1_SPEED_IIR_ZC_B0: calculateM1SpeedIirZCB0(inputStructure),
        M1_SPEED_IIR_ZC_B1: calculateM1SpeedIirZCB1(inputStructure),
        M1_SPEED_IIR_ZC_A1: calculateM1SpeedIirZCA1(inputStructure)
    }
}