/**
 * calculates precision of given number
 * @param {number} value 
 * @param {number} decimalPlaces
 * @returns {string}
 */
export function formatNumber(value, decimalPlaces) {
    // Add comprehensive input validation
    if (value === null || value === undefined) {
        return "";
    }
    
    if (typeof (value) === "number" && !isNaN(value)) {
        if (Number.isInteger(value)) {
            return Number.parseFloat(value).toFixed(1);
        } else if (!Number.isInteger(value) && !isNaN(value)) {
            try {
                const valueStr = value.toString();
                const splitResult = valueStr.split(".");
                
                // Add safety check for split result
                if (splitResult && splitResult.length > 1 && splitResult[1] && splitResult[1].length) {
                    const precision = splitResult[1].length;
                    return precision < decimalPlaces ? value.toString() : value.toPrecision(decimalPlaces);
                } else {
                    return value.toString();
                }
            } catch (error) {
                console.warn('Error formatting number:', error);
                return value.toString();
            }
        }
    } else if (typeof (value) === "boolean") {
        return value;
    } else if (typeof (value) === "string") {
        // Handle string inputs gracefully
        const numValue = parseFloat(value);
        if (!isNaN(numValue)) {
            return formatNumber(numValue, decimalPlaces);
        }
        return value;
    }
    
    return "";
}
/**
 * searches through the grid design and looks for id-specific field
 * @param {string} id
 * @param {object} data 
 * @param {function} callback 
 */
export function getFieldById(id, data, callback) {
    getField(data, function (field) {
        if (field.id === id) {
            callback(field);
        }
    });
}

/**
 * simplifies the nested for-loop for data grid 
 * @param {object} data 
 * @param {function} callback 
 */
export function getField(data, callback) {
    Object.keys(data).forEach(function (io) {
        Object.keys(data[io]).forEach(function (key) {
            Object.keys(data[io][key]).forEach(function (field) {
                callback(data[io][key][field]);
            })
        });
    });
}

export function getMainFieldById(data, id) {
    var ret;
    buildStructure(data, function (canvas, field) {
        if (field.id === id) {
            ret = field;
        }
    });
    return ret;
} 

/**
 * extracts a single field from data struture and calls a function on it 
 * @param {object} data 
 * @param {function} callback 
 */
export function buildStructure(data, callback) {
    Object.keys(data).forEach(function (canvas) {
        Object.keys(data[canvas]).forEach(function (index) {
            callback(canvas, data[canvas][index]);          
        })
    })
}

/**
 * checks if all arguments passed to a function are numbers
 * @param {IArguments or any other iterable} params 
 * @param {function} callback 
 */
export function checkIfParamsAreNumbers(params, callback) {
    var isValid = true;
    [...params].forEach(param => {
        if (typeof (param) !== "number") {
            isValid = false;
        }
    });
    callback(isValid);
}