<template>
  <section ref="speedLoopCanvas" v-if="visible">
    <div class="alert alert-warning" v-if="isWarning">
      <strong>Warning! </strong>
      <slot> {{ warningMessage }}</slot>
    </div>
    <div class="alert alert-danger" v-if="isWrong">
      <strong>Error! </strong>
      <slot> {{ errorMessage }}</slot>
    </div>
    <div class="row">
      <div class="col border-end" v-for="column in columns" :key="column.index">
        <div v-for="section in column.sections" :key="section.name">
          <hr />
          <span class="text-uppercase fw-bold">
            {{ section.name }}
          </span>
          <div class="row m-1" v-for="item in section.fields" :key="item.id" :title="item.hint">
            <div class="col-4 d-flex align-items-center justify-content-end">
              <label :for="item.id"> {{ item.label }}: </label>
            </div>
            <div class="col-4">
              <input :class="item.className.field + ' ' + item.className.color" autocomplete="off" :ref="item.id"
                :disabled="item.disabled" v-model.number="item.value" :type="item.type"
                @keyup.enter="$event.target.blur()" @blur="sendValue(item.id, item.value, true)"
                @change="checkId(item.id, item.value)" />
            </div>
            <div class="col-1 d-flex align-items-center justify-content-start">
              <label v-if="item.hasUnit" :for="item.id" v-html="'[' + item.unit + ']'">
              </label>
            </div>
          </div>
          <hr />
        </div>
      </div>
      <hr />
    </div>
  </section>
</template>

<script>
import { getFieldById } from "../logic/utils";
import { toBaseValue, setFieldFromBaseValue, addPrefixToUnit } from "../functions/scalingConfig";
export default {
  name: "SpeedLoopCanvas",
  props: [
    "visible",
    "needData",
    "speedLoopOutputs",
    "reloadData",
    "limits",
  ],
  data() {
    return {
      isWrong: false,
      isWarning: false,
      warningMessage: "",
      errorMessage: "",
      score: [],
      columns: [
        {
          index: "column1",
          sections: [
            {
              name: "Loop parameters",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopSampleTime",
                  label: "Sample time Ts",
                  unit: "sec",
                  disabled: true,
                  value: "",
                  hasUnit: true,
                  hint: "Slow control loop period.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.00001,
                    maxRange: 0.01,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopF0",
                  label: "Bandwidth F0",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Speed controllers' bandwidth.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 200,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopKsi",
                  label: "Attenuation ξ",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Speed controllers' attenuation.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 10.0,
                  },
                },
              ],
            },
            {
              name: "Speed ramp",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIncUp",
                  label: "Upper limit",
                  unit: "rpm/sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Required speed maximal acceleration.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 50000,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIncDown",
                  label: "Lower limit",
                  unit: "rpm/sec",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Required speed maximal deceleration.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 50000,
                  },
                },
              ],
            },
            {
              name: "Actual speed filter",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopCutOffFreq",
                  label: "Cut-off freq",
                  unit: "Hz",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Speed filter bandwidth.",
                  validation: {
                    type: "number",
                    isFloat: false,
                    minRange: 0,
                    maxRange: 1000,
                  },
                },
              ],
            },
            {
              name: "Speed PI controller limits",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopUpperLimit",
                  label: "Upper limit",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Maximal required Q-axis current (speed controller's output).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0,
                    maxRange: "",
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopLowerLimit",
                  label: "Lower limit",
                  unit: "A",
                  disabled: false,
                  value: "",
                  hasUnit: true,
                  hint: "Minimal required Q-axis current (speed controller's output).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: "",
                    maxRange: 0,
                  },
                },
              ],
            },
          ],
        },
        {
          index: "column2",
          sections: [
            {
              name: "Speed PI controller constants",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopSLKp",
                  label: "Proportional gain",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated OR manually entered proportional gain of Speed controller (in Z-domain).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopSLKi",
                  label: "Integration gain",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated OR manually entered integration gain of Speed controller (in Z-domain).",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "checkbox",
                  className: {
                    field: "form-check-input",
                    color: "",
                  },
                  id: "speedLoopManualConstantTunning",
                  label: "Manual constant tuning",
                  unit: "",
                  disabled: false,
                  value: "",
                  hasUnit: false,
                  hint: "When enabled, speed controller constants are tuned manually.",
                },
              ],
            },
            {
              name: "Speed zero cancellation filter constants",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIIRB0_ZC",
                  label: "B0",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR zero cancellation filter B0 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIIRB1_ZC",
                  label: "B1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR zero cancellation filter B1 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIIRA1_ZC",
                  label: "A1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR zero cancellation filter (-1)*A1 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
              ],
            },
            {
              name: "Speed feedback filter constants",
              fields: [
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIIRB0",
                  label: "B0",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR filter B0 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIIRB1",
                  label: "B1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR filter B1 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
                {
                  type: "input",
                  className: {
                    field: "form-control",
                    color: "",
                  },
                  id: "speedLoopIIRA1",
                  label: "A1",
                  unit: "",
                  disabled: true,
                  value: "",
                  hasUnit: false,
                  hint: "Calculated Speed IIR filter A1 constant.",
                  validation: {
                    type: "number",
                    isFloat: true,
                    minRange: 0.0,
                    maxRange: 100.0,
                  },
                },
              ],
            },
          ],
        },
      ],
    };
  },
  methods: {
    /**
     * simplifies grid structure for data manipulation. If new *section* is added / deleted it has to be manually changed
     * @param {none}
     * @returns {object} grid data divided into input / output group
     */
    getData() {
      const inputData = this.columns[0].sections;
      const outputData = this.columns[1].sections;
      const loopParametersData = inputData[0].fields;
      const speedRampData = inputData[1].fields;
      const actualSpeedFilterData = inputData[2].fields;
      const speedPIControllerLimitsData = inputData[3].fields;
      const speedPIControllerConstantsData = outputData[0].fields;
      const speedFeedbackControllerConstantsData = outputData[1].fields;
      const speedZCFilterConstantsData = outputData[2].fields;
      return {
        input: {
          loopParametersData,
          speedRampData,
          actualSpeedFilterData,
          speedPIControllerLimitsData,
        },
        output: {
          speedPIControllerConstantsData,
          speedFeedbackControllerConstantsData,
          speedZCFilterConstantsData,
        },
      };
    },
    /**
     * sets a value to a specific field given an id
     * @param {string} id
     * @param {number} baseValue
     * @returns {none}
     */
    setData(id, baseValue) {
      if (id === "speedLoopManualConstantTunning") {
        this.setTuning(baseValue);
      }
      getFieldById(id, this.getData(), function (field) {
        setFieldFromBaseValue(field, baseValue);
      });
    },
    switchFields(fields, value) {
      Object.keys(fields).forEach((field) => {
        if (
          fields[field].id !== "speedLoopManualConstantTunning" &&
          fields[field].id !== "speedLoopSampleTime"
        ) {
          fields[field].disabled = value;
        }
      });
    },
    checkId(id, value) {
      if (id === "speedLoopManualConstantTunning") {
        this.sendValue(id, value, true);
      }
    },
    setTuning(value) {
      const loopParameters = this.getData().input.loopParametersData;
      const controllerConstants = this.getData().output.speedPIControllerConstantsData;
      this.switchFields(loopParameters, value);
      this.switchFields(controllerConstants, !value);
    },
    /**
     * validates given input, if valid emits it to the main canvas
     * @param {string} id
     * @param {number} displayValue
     * @param {boolean} needsValidation
     * @returns {none}
     */
    sendValue(id, displayValue, needsValidation) {
      // After first interaction with input, displayValue might be a string, so convert to number
      // console.log("CurrLopp 1: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);
      if(typeof displayValue == 'string'){
        displayValue = Number(displayValue); // Convert string to number
      }
      //console.log("CurrLoop 2: id: ", id, typeof id, "dispValue: ", displayValue, "datatype: ", typeof displayValue);

      getFieldById(id, this.getData(), (field) => {
        if (id === "speedLoopManualConstantTunning") {
          this.setTuning(displayValue);
        } else {
          const setError = () => {
            this.isWrong = true;
            field.className.color = "bg-danger";
            this.warningMessage = this.warningMessage.replace(war, "");
            if (this.warningMessage === "") {
              this.isWarning = false;
            }
            if (!this.errorMessage.includes(err)) {
              this.errorMessage += err;
            }
          };
          const setWarning = () => {
            this.isWarning = true;
            field.className.color = "bg-warning";
            this.errorMessage = this.errorMessage.replace(err, "");
            if (this.errorMessage === "") {
              this.isWrong = false;
            }
            if (!this.warningMessage.includes(war)) {
              this.warningMessage += war;
            }
          };
          const type = field.validation.isFloat ? "float" : "integer";
          var war = `${field.label} is not in range [${field.validation.minRange} - ${field.validation.maxRange}]! `;
          const err = `${field.label} value is not a number of type ${type}! `;
          if (
            typeof displayValue !== "number" ||
            isNaN(displayValue) ||
            (!Number.isInteger(displayValue) && !field.validation.isFloat)
          ) {
            setError();
          } else if (
            (needsValidation && field.validation.minRange > displayValue) ||
            displayValue > field.validation.maxRange
          ) {
            setWarning();
          } else {
            this.errorMessage = this.errorMessage.replace(err, "");
            this.warningMessage = this.warningMessage.replace(war, "");
            field.className.color = "";
            if (this.warningMessage === "") {
              this.isWarning = false;
            }
            if (this.errorMessage === "") {
              this.isWrong = false;
            }
          }
        }
        
        field.value = displayValue;
      });
      
      if (!this.isWrong) {
        const baseValue = toBaseValue(id, displayValue);
        this.$emit("value-was-sent", [id, baseValue]);
        this.errorMessage = "";
      }
    },
    initializeUnits() {
      try {
        const allFields = [
          ...this.getData().input.loopParametersData,
          ...this.getData().input.speedRampData,
          ...this.getData().input.actualSpeedFilterData,
          ...this.getData().input.speedPIControllerLimitsData,
          ...this.getData().output.speedPIControllerConstantsData,
          ...this.getData().output.speedFeedbackControllerConstantsData,
          ...this.getData().output.speedZCFilterConstantsData,
        ];

        allFields.forEach(field => {
          if (field && field.type === 'input' && field.id && field.unit) {
            if (!field.originalUnit) {
              field.originalUnit = field.unit;
            }
            field.unit = addPrefixToUnit(field.id, field.originalUnit);
          }
        });
      } catch (error) {
        console.warn('Error initializing units:', error);
      }
    },
  },
  mounted() {
    this.initializeUnits();
  },
  watch: {
    speedLoopOutputs: function (newVal) {
      const thisRef = this;
      if (newVal) {
        const id = newVal.id;
        const baseVal = newVal.value;
        const outputs = [
          "speedLoopSLKp",
          "speedLoopSLKi",
          "speedLoopIIRB0",
          "speedLoopIIRB1",
          "speedLoopIIRA1",
          "speedLoopIIRB0_ZC",
          "speedLoopIIRB1_ZC",
          "speedLoopIIRA1_ZC",
        ];
        getFieldById(id, thisRef.getData(), function (field) {
          if (outputs.includes(id) && !isNaN(baseVal)) {
            setFieldFromBaseValue(field, baseVal);
          }
        });
      }
    },
    needData: function (newVal) {
      if (newVal) {
        this.$emit("test-data-was-sent", this.getData());
      }
    },
    reloadData: function (newVal) {
      const thisRef = this;
      if (newVal) {
        thisRef.isWrong = false;
        thisRef.errorMessage = "";
        thisRef.setData(newVal.id, newVal.value);
      }
    },
    limits: function (newVal) {
      if (newVal) {
        const id = newVal.id;
        const value = newVal.value;
        const upperLimit = this.getData().input.speedPIControllerLimitsData[0];
        const lowerLimit = this.getData().input.speedPIControllerLimitsData[1];
        const setLimit = {
          parametersImax: () => {
            upperLimit.validation.maxRange = value;
            lowerLimit.validation.minRange = -value;
          },
        };
        if (typeof setLimit[id] !== "undefined") {
          setLimit[id]();
        }
      }
    },
  },
};
</script>