const constants = require("./numeralConstants");
import { checkIfParamsAreNumbers } from "../logic/utils";


/**
 * calculates current loop limit
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1CloopLimit(inputStructure) {
    const currentLoopOutputLimit = inputStructure.currentLoop.currentLoopOutputLimit;
    var ret;
    checkIfParamsAreNumbers([currentLoopOutputLimit], (isValid) => {
        // Max voltage generated bz SVM from UDCB
        ret = isValid ? (currentLoopOutputLimit / constants.UmaxCoeff) / 100 : NaN;
    });
    return ret;
}

/**
 * calculates D_Kp factor
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1DKpGain(inputStructure) {
    const currentLoopKsi = inputStructure.currentLoop.currentLoopKsi;
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const parametersLd = inputStructure.parameters.parametersLd;
    const parametersRs = inputStructure.parameters.parametersRs;
    var ret;
    checkIfParamsAreNumbers([currentLoopKsi, currentLoopF0, parametersLd, parametersRs], (isValid) => {
        ret = isValid ? (2 * currentLoopKsi * 2 * Math.PI * currentLoopF0 * parametersLd) - parametersRs : NaN;
        // console.log("CurrentLoop DKpGain:", ret);
    });
    return ret;
}

/**
 * calculates D_Ki factor
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1DKiGain(inputStructure) {
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const parametersLd = inputStructure.parameters.parametersLd;
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var ret;
    checkIfParamsAreNumbers([currentLoopF0, parametersLd], (isValid) => {
        ret = isValid ? ((Math.pow((2 * Math.PI * currentLoopF0), 2) * parametersLd) * currentLoopSampleTime / constants.DiscMethodFactor) : NaN;
        // console.log("CurrentLoop DKiGain:", ret);
    });
    return ret;
}

/**
 * calculates Q_Kp factor
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1QKpGain(inputStructure) {
    const currentLoopKsi = inputStructure.currentLoop.currentLoopKsi;
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const parametersLq = inputStructure.parameters.parametersLq;
    const parametersRs = inputStructure.parameters.parametersRs;
    var ret;
    checkIfParamsAreNumbers([currentLoopKsi, currentLoopF0, parametersLq, parametersRs], (isValid) => {
        ret = isValid ? (2 * currentLoopKsi * 2 * Math.PI * currentLoopF0 * parametersLq) - parametersRs : NaN;
        // console.log("CurrentLoop QKpGain:", ret);
    });
    return ret;
}

/**
 * calculates Q_Ki factor
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1QKiGain(inputStructure) {
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const parametersLq = inputStructure.parameters.parametersLq;
    const currentLoopSampleTime = inputStructure.currentLoop.currentLoopSampleTime;
    var ret;
    checkIfParamsAreNumbers([currentLoopF0, parametersLq], (isValid) => {
        ret = isValid ? ((Math.pow((2 * Math.PI * currentLoopF0), 2) * parametersLq) * currentLoopSampleTime / constants.DiscMethodFactor) : NaN;
        // console.log("CurrentLoop QKiGain:", ret);
    });
    return ret;
}

/**
 * calculates Iq zero cancellation filter B0
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1QIirZCB0(inputStructure) {
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const currentLoopSampleTime = 1/currentLoopF0;
    const kp_q = calculateM1QKpGain(inputStructure);
    const ki_q_z = calculateM1QKiGain(inputStructure); // in Z-domain 
    const ki_q_s = ki_q_z * (2/currentLoopSampleTime); // in S domain
    const Ti = kp_q/ki_q_s;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, Ti], (isValid) => {
        ret = isValid ? (currentLoopSampleTime/(currentLoopSampleTime + 2*Ti)) : NaN;
        // console.log("CurrentLoop Q_ZC_B0:", ret);
    });
    return ret;
}

/**
 * calculates Iq zero cancellation filter B1
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1QIirZCB1(inputStructure) {
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const currentLoopSampleTime = 1/currentLoopF0;
    const kp_q = calculateM1QKpGain(inputStructure);
    const ki_q_z = calculateM1QKiGain(inputStructure); // in Z-domain 
    const ki_q_s = ki_q_z * (2/currentLoopSampleTime); // in S domain
    const Ti = kp_q/ki_q_s;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, Ti], (isValid) => {
        ret = isValid ? (currentLoopSampleTime/(currentLoopSampleTime + 2*Ti)) : NaN;
        // console.log("CurrentLoop Q_ZC_B1:", ret);
    });
    return ret;
}

/**
 * calculates Iq zero cancellation filter A1
 * @param {object} inputStructure 
 * @returns {number}
 */
function calculateM1QIirZCA1(inputStructure) {
    const currentLoopF0 = inputStructure.currentLoop.currentLoopF0;
    const currentLoopSampleTime = 1/currentLoopF0;
    const kp_q = calculateM1QKpGain(inputStructure);
    const ki_q_z = calculateM1QKiGain(inputStructure); // in Z-domain 
    const ki_q_s = ki_q_z * (2/currentLoopSampleTime); // in S domain
    const Ti = kp_q/ki_q_s;
    var ret;
    checkIfParamsAreNumbers([currentLoopSampleTime, Ti], (isValid) => {
        ret = isValid ? ((-1)*(currentLoopSampleTime-2*Ti)/(currentLoopSampleTime+2*Ti)) : NaN;
        // console.log("CurrentLoop Q_ZC_A1:", ret);
    });
    return ret;
}

/**
 * export function calculates the whole parameters output structure
 * @param {object} inputStructure 
 * @returns {object}
 */
export function calculateParams(inputStructure) {
    // console.log("Calculating Current Loop...");
    return {
        M1_CLOOP_LIMIT: calculateM1CloopLimit(inputStructure),
        M1_D_KP_GAIN: calculateM1DKpGain(inputStructure),
        M1_D_KI_GAIN: calculateM1DKiGain(inputStructure),
        M1_Q_KP_GAIN: calculateM1QKpGain(inputStructure),
        M1_Q_KI_GAIN: calculateM1QKiGain(inputStructure),
        M1_Q_IIR_ZC_B0: calculateM1QIirZCB0(inputStructure),
        M1_Q_IIR_ZC_B1: calculateM1QIirZCB1(inputStructure),
        M1_Q_IIR_ZC_A1: calculateM1QIirZCA1(inputStructure)
    }
}