import { getMainFieldById, getFieldById } from "../logic/utils";
import { calculateConversionFactor } from '../functions/scalingConfig';

/* Fixed ratios between nominal parameters and input parameters and other defines */
const SPIN_TO_MID_DELAY        = 10000               /* Delay from 'Spin' to 'MID' state machine [ms] (maximum is hardcoded 20 s) */
const MID_TO_SPIN_DELAY        = 0                   /* Delay from 'MID' to 'Spin' state machine [ms] (maximum is hardcoded 20 s) */
const MID_PPIS_INOM_RATIO      = 0.2;                /* I Nom         -> MID: Config Pp Id Meas */
const MID_PPIS_WNOM_RATIO      = (1 / 60.0) * 0.1;   /* N Nom [rpm]   -> MID: Config Pp Freq El. Required [Hz] */
const MID_ELMEAS_INOM_RATIO    = 0.5;                /* I Nom * ratio -> MID: Config El I DC nominal */
const MID_MECHMEAS_INOM_RATIO  = 1;                  /* I Nom * ratio -> MID: Config Mech I Nominal */
const MID_MECHMEAS_NNOM_RATIO  = 1;                  /* N Nom * ratio -> MID: Config Mech N Nominal */

let cancelWriteOperation       = false;              /* Cancellation flag for "writeFmstrValues" function */
let writeOperationInProgress   = false;              /* FreeMASTER write operation in progress flag */

/**
 * Common handler for all MID user buttons
 * @param {object} pcm - FreeMASTER PCM interface.
 * @param {object} data - MCAT data object containing field values.
 * @param {object} midThisRef - 'this' reference to MID.
 * @param {object} item - Button item object.
 */
export async function midUserButtonHandler(pcm, data, midThisRef, item) { 
  const statusLine    = midThisRef.getData().output.statusMidOutData[1];
  const statusLineSec = midThisRef.getData().output.statusMidOutData[2];
  statusLine.value = '';
  statusLineSec.value = "";
  const functionName = `${item.id}Function`;
  const functionNameMap = {
    midPolePairIAUserButtonFunction,
    midElParamMeasUserButtonFunction,
    midMechParamMeasUserButtonFunction,
  };
  const buttonFunction = functionNameMap[functionName];
  if (typeof buttonFunction !== 'function') {
    console.log(`Function "${functionName}" not found.`);
    return;
  }

  /* Update buttons and trigger required measurement */
  const midButtons = [
      midThisRef.getData().input.polePairISInData[0],
      midThisRef.getData().output.elParamMeasOutData[0],
      midThisRef.getData().output.mechParamMeasOutData[0]
  ];
  if(item.value === 1) {
    midThisRef.updateButtons(midButtons, { 
      disabled: false,
      value: 0,
      className: "nxp-light-blue",
      buttonLabel: "START"
    });
    /* Signal stopped measurement (in case of Pp Assisst signal finished measurement) */
    statusLine.value = `ℹ️ ${styleText("INFO", "INFO")} ${item.id === 'midPolePairIAUserButton' ? item.textFinish : item.textStop}`;
    midDeactivateMidFunction(pcm, data, midThisRef);
  } else {
    midThisRef.updateButtons(midButtons, { 
      disabled: true,
      value: 0,
      className: "bg-secondary",
      buttonLabel: "START"
    });
    midThisRef.mcatControl = true;
    buttonFunction(pcm, data, midThisRef);
  }
}

/**
 * Stop 'MID' state machine process and enter 'Spin' state machine
 * @param {object} pcm - FreeMASTER PCM interface.
 * @param {object} data - MCAT data object containing field values.
 * @param {object} midThisRef - 'this' reference to MID.
 */
export async function midDeactivateMidFunction(pcm, data, midThisRef) { 
  const fieldConfig = [];

  await transMid2Spin(pcm, midThisRef, fieldConfig);

  fieldConfig.push(
    /* Enter 'Spin' state machine */
    { name: "APP: MID to Spin request", value: 1},
  );

  /* Update FreeMaster variables */
  if (!(await writeFmstrValues(data, pcm, fieldConfig, midThisRef))) {
    /* Invalid values fetched from IDs, stop process */
    resetButtonsState(midThisRef);
    return false;
  }
  return true;
}

/**
 * Start pole-pair identification assistant
 * @param {object} pcm - FreeMASTER PCM interface.
 * @param {object} data - MCAT data object containing field values.
 * @param {object} midThisRef - 'this' reference to MID.
 */
async function midPolePairIAUserButtonFunction(pcm, data, midThisRef) {
  console.log("Switching to MID state machine, updating MID input parameters and starting pole-pair identification...");
  const fieldConfig = [];

  await transSpin2Mid(pcm, midThisRef, fieldConfig);

  fieldConfig.push(
    /* Enter 'MID' state machine */
    { name: "APP: Spin to MID request", value: 1                                                  },
    /* Update input parameters */
    { name: "MID: Config Pp Id",     id: "midInParamINom", ratio: MID_PPIS_INOM_RATIO             },
    { name: "MID: Config Pp Freq",   id: "midInParamNNom", ratio: MID_PPIS_WNOM_RATIO             },
    /* Clear DIAG fault, select measurement type and set Start command */
    { name: "DIAG: Fault clear",     value: 1                                                     },
    { name: "MID: Measurement Type", value: 0                                                     },
    { name: "MID: Command",          value: 1                                                     }
  );

  /* Update FreeMaster variables */
  if (!(await writeFmstrValues(data, pcm, fieldConfig, midThisRef))) {
    /* Invalid values fetched from IDs, stop process */
    resetButtonsState(midThisRef);
    return false;
  }
  
  return true;
}

